/**
 * Re-parse the seeded case-law fixtures through the current parsers.
 *
 *   bun apps/api/scripts/reparse-case-law-fixtures.ts --write
 *   bun apps/api/scripts/reparse-case-law-fixtures.ts --check
 *
 * Registered as the `case-law-fixture-reparse` generator
 * (scripts/generated-files.ts), so a parser or AST change that alters a
 * fixture is regenerated by autofix and caught by the generated-files guard.
 * The rules per row live in `lib/case-law-fixture-reparse.ts`:
 *
 * - rows recorded with `source_raw` are re-parsed by their adapter;
 * - rows exported without raw keep their document and only take the
 *   read-time AST repairs, so a parser change cannot reach them (a field a
 *   new parser fills, such as a paragraph `number`, appears only on rows
 *   that carry raw; re-record a fixture with raw to get it);
 * - a row whose new document changes the input of its stored analysis fails
 *   the run instead of re-stamping the fingerprint.
 *
 * `--check` writes nothing and exits 1 when any archive would change or any
 * row fails. `--write` rewrites only archives whose content changes, and
 * still exits 1 on a failed row.
 */

import { panic } from "better-result";
import { readdir } from "node:fs/promises";
import path from "node:path";
import { gzipSync } from "node:zlib";

import {
  CASE_LAW_FIXTURES_DIR,
  readCaseLawFixtureFile,
} from "./lib/case-law-fixture-analyses";
import {
  adapterReparser,
  type ReparseFixtureRow,
  reparseFixtureRow,
} from "./lib/case-law-fixture-reparse";

const write = process.argv.includes("--write");
const check = process.argv.includes("--check");
if (write === check) {
  console.error(
    "Usage: bun apps/api/scripts/reparse-case-law-fixtures.ts --write|--check",
  );
  process.exit(1);
}

const isRow = (value: unknown): value is ReparseFixtureRow =>
  typeof value === "object" &&
  value !== null &&
  typeof Reflect.get(value, "case_number") === "string" &&
  typeof Reflect.get(value, "court") === "string" &&
  typeof Reflect.get(value, "country") === "string" &&
  typeof Reflect.get(value, "language") === "string";

const failures: string[] = [];
const changed: string[] = [];
const names = (await readdir(CASE_LAW_FIXTURES_DIR))
  .filter((entry) => entry.endsWith(".json.gz"))
  .toSorted();

for (const name of names) {
  const fixturePath = path.join(CASE_LAW_FIXTURES_DIR, name);
  const fixture: { source?: unknown; decisions: unknown[] } =
    await readCaseLawFixtureFile(fixturePath);
  const source = fixture.source;
  const adapterKey =
    typeof source === "object" && source !== null
      ? Reflect.get(source, "adapter_key")
      : undefined;
  if (typeof adapterKey !== "string") {
    failures.push(`${name}: the fixture names no adapter`);
    continue;
  }
  let fileChanged = false;
  const decisions: unknown[] = [];
  for (const decision of fixture.decisions) {
    if (!isRow(decision)) {
      failures.push(`${name}: a decision row lacks its identity fields`);
      decisions.push(decision);
      continue;
    }
    const result = await reparseFixtureRow({
      adapterKey,
      row: decision,
      reparse: adapterReparser,
    });
    switch (result.type) {
      case "unchanged":
        decisions.push(decision);
        break;
      case "changed":
        fileChanged = true;
        changed.push(`${name} ${decision.case_number} (${result.via})`);
        decisions.push(result.row);
        break;
      case "failed":
        failures.push(`${name} ${result.message}`);
        decisions.push(decision);
        break;
      default:
        result satisfies never;
        panic(`Unhandled fixture row result in ${name}`);
    }
  }
  if (fileChanged && write) {
    await Bun.write(
      fixturePath,
      gzipSync(JSON.stringify({ ...fixture, decisions })),
    );
  }
}

for (const line of changed) {
  console.log(`${write ? "Rewrote" : "Stale"}: ${line}`);
}
for (const failure of failures) {
  console.error(failure);
}
if (failures.length > 0 || (check && changed.length > 0)) {
  if (check && changed.length > 0) {
    console.error(
      "case-law fixtures: run `bun apps/api/scripts/reparse-case-law-fixtures.ts --write` and commit the archives.",
    );
  }
  process.exit(1);
}
if (changed.length === 0) {
  console.log("case-law fixtures: every row matches the current parsers.");
}
